```json
{
  "conditions": {
    "basis_identification": {
      "status": "pass",
      "note": "The record explicitly identifies the legal framework (Title VII, ADEA), the investigative standard applied (McDonnell Douglas three-part test), and the Agency's stated reasons for each determination (e.g., non-selection based on comparative qualifications, performance ratings based on supervisor authority and objective performance)."
    },
    "reasoning_traceability": {
      "status": "review",
      "note": "While the record traces the Agency's conclusions through the McDonnell Douglas framework, the investigative process itself—how the 28 incidents were evaluated, what evidence was weighed, and how factual findings were reached—is not detailed; only the Agency's final rationale is presented."
    },
    "cold_reviewer_clarity": {
      "status": "review",
      "note": "A reviewer could reconstruct the claims and Agency conclusions from the record, but lacks visibility into the underlying investigative findings, witness statements, documentary evidence, or credibility assessments that would enable full independent evaluation of the basis for each determination."
    },
    "accountability_support": {
      "status": "review",
      "note": "The record supports the Agency's stated legitimate nondiscriminatory reasons but does not explicitly document the evidentiary record (interview notes, performance data, selection panel materials) that would establish sufficiency of support for each conclusion."
    },
    "temporal_reconstructability": {
      "status": "pass",
      "note": "The record provides a clear chronology of alleged incidents from April 2017 through June 2018, with specific dates for each claim, and notes the timing of the Agency's investigation, ROI issuance, and FAD decision."
    }
  },
  "remediation_note": "To achieve full compliance, the record should incorporate or reference the Report of Investigation findings (factual determinations, evidence evaluated, and credibility assessments for each of the 28 incidents) and explicitly document how the Agency applied the McDonnell Douglas burden-shifting analysis to each claim category, including findings on pretext.",
  "finding": {
    "ai_function": "summarization",
    "condition_triggered": "reasoning_traceability, cold_reviewer_clarity, accountability_support",
    "compliant_version": "A compliant record would include a background section (as present) plus an Investigative Findings section that summarizes, for each claim or claim category, the material factual findings from the ROI (who said what, when, to whom, and with what corroboration), the evidence considered, and the logical connection between those findings and the Agency's application of the McDonnell Douglas test, enabling a subsequent reviewer to verify whether the conclusions follow from the evidence without access to the full investigative file."
  }
}
```
